const ASSETS={"/":{"body":"<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\" />\n  <meta name=\"theme-color\" content=\"#12213f\" />\n  <title>GLN Karen Typing Center</title>\n  <meta name=\"description\" content=\"Type, practice, play, and learn S'gaw Karen Unicode at GLN Karen Typing Center.\" />\n  <link rel=\"icon\" type=\"image/png\" href=\"logo.png\" />\n  <link rel=\"stylesheet\" href=\"padauk.css\" />\n  <link rel=\"stylesheet\" href=\"styles.css\" />\n  <link rel=\"stylesheet\" href=\"practice.css\" />\n  <link rel=\"stylesheet\" href=\"games.css\" />\n  <link rel=\"stylesheet\" href=\"race.css\" />\n</head>\n<body>\n  <main class=\"app-shell\">\n    <header class=\"topbar\">\n      <a class=\"brand\" href=\"#\" aria-label=\"GLN Karen Typing Center home\">\n        <img class=\"brand-logo\" src=\"logo.png\" alt=\"GLN Karen Typing logo\" />\n        <span><strong>GLN Karen Typing Center</strong><small>ကညီကျိာ် လံာ်တီၢ်</small></span>\n      </a>\n      <nav class=\"topnav\" aria-label=\"Main sections\">\n        <button class=\"active\" id=\"navType\" type=\"button\">Type</button>\n        <button id=\"navPractice\" type=\"button\">Practice</button>\n        <button id=\"navGames\" type=\"button\">Games</button>\n      </nav>\n    </header>\n\n    <section class=\"workspace\" id=\"typeView\" aria-labelledby=\"editor-title\">\n      <div class=\"workspace-heading\">\n        <div><p class=\"eyebrow\">S’GAW KAREN · ကညီကျိာ်</p><h1 id=\"editor-title\">Type in Karen</h1></div>\n        <p class=\"hint\">KarenKNU layout — use your English keyboard or tap below.</p>\n      </div>\n\n      <div class=\"editor-card\">\n        <textarea id=\"editor\" lang=\"ksw\" spellcheck=\"false\" autofocus placeholder=\"တီၢ်လံာ်ဖဲအံၤ…\" aria-label=\"Karen text editor\"></textarea>\n        <div class=\"editor-footer\">\n          <span id=\"count\">0 characters</span>\n          <div class=\"actions\">\n            <button class=\"button ghost\" id=\"undo\" type=\"button\" aria-label=\"Undo last change\">↶ <span>Undo</span></button>\n            <button class=\"button ghost\" id=\"selectAll\" type=\"button\">Select all</button>\n            <button class=\"button danger\" id=\"clear\" type=\"button\">Clear</button>\n            <button class=\"button primary\" id=\"copy\" type=\"button\"><span id=\"copyIcon\">▣</span> <span id=\"copyText\">Copy text</span></button>\n          </div>\n        </div>\n      </div>\n\n      <section class=\"keyboard-card\" aria-label=\"On-screen Karen keyboard\">\n        <div class=\"keyboard-top\">\n          <div class=\"mode-switch\" role=\"group\" aria-label=\"Keyboard layer\">\n            <button class=\"active\" id=\"normalMode\" type=\"button\">Normal</button>\n            <button id=\"shiftMode\" type=\"button\">Shift</button>\n          </div>\n          <button class=\"layout-note\" id=\"toggleGuide\" type=\"button\">Keyboard guide <span>⌄</span></button>\n        </div>\n        <div class=\"guide\" id=\"guide\" hidden>This is the KarenKNU S’gaw Karen layout. Each key shows its English shortcut. Press Shift for the second layer.</div>\n        <div class=\"keyboard\" id=\"keyboard\"></div>\n      </section>\n\n      <p class=\"privacy\"><span aria-hidden=\"true\">●</span> Your text stays on this device.</p>\n    </section>\n\n    <section class=\"workspace games-view\" id=\"gamesView\" aria-labelledby=\"games-title\" hidden>\n      <div class=\"games-heading\">\n        <div><p class=\"eyebrow\">KAREN TYPING GAMES</p><h1 id=\"games-title\">Choose a challenge</h1></div>\n        <p class=\"hint\">Practice Karen words while building speed and accuracy.</p>\n      </div>\n      <div class=\"game-grid\" id=\"gameGrid\">\n        <button class=\"game-card race-card\" data-game=\"race\" type=\"button\"><span class=\"game-icon\">🏁</span><span><strong>Classroom Car Race</strong><small>Create one room code. Students join with their names and race live.</small></span><em>Race →</em></button>\n        <button class=\"game-card sprint-card\" data-game=\"sprint\" type=\"button\"><span class=\"game-icon\">⚡</span><span><strong>Word Sprint</strong><small>Type as many Karen words as you can in 45 seconds.</small></span><em>Play →</em></button>\n        <button class=\"game-card rain-card\" data-game=\"rain\" type=\"button\"><span class=\"game-icon\">↓</span><span><strong>Falling Words</strong><small>Type each word before it reaches the bottom.</small></span><em>Play →</em></button>\n      </div>\n      <section class=\"game-stage\" id=\"gameStage\" hidden aria-live=\"polite\">\n        <div class=\"game-stage-top\"><button class=\"back-games\" id=\"backGames\" type=\"button\">← All games</button><strong id=\"activeGameTitle\">Word Sprint</strong><button class=\"button ghost\" id=\"restartGame\" type=\"button\">↻ Restart</button></div>\n        <div class=\"game-stats\"><div><span>Score</span><strong id=\"gameScore\">0</strong></div><div><span id=\"gameMiddleLabel\">Streak</span><strong id=\"gameMiddle\">0</strong></div><div><span id=\"gameTimeLabel\">Time</span><strong id=\"gameTime\">45</strong></div></div>\n        <div class=\"playfield\" id=\"playfield\">\n          <div class=\"game-message\" id=\"gameMessage\"><strong>Ready?</strong><span>Press Start to begin.</span><button class=\"button primary\" id=\"startGame\" type=\"button\">Start game</button></div>\n          <div class=\"word-challenge\" id=\"wordChallenge\" hidden><span class=\"challenge-label\" id=\"challengeLabel\">TYPE THIS WORD</span><strong id=\"challengeWord\" lang=\"ksw\"></strong><div class=\"typed-answer\" id=\"typedAnswer\" lang=\"ksw\"></div></div>\n          <div class=\"falling-word\" id=\"fallingWord\" lang=\"ksw\" hidden></div>\n        </div>\n        <p class=\"game-tip\" id=\"gameTip\">Use your English keyboard or tap the highlighted key below.</p>\n        <div class=\"game-keyboard keyboard\" id=\"gameKeyboard\"></div>\n      </section>\n      <section class=\"race-stage\" id=\"raceStage\" hidden aria-live=\"polite\">\n        <div class=\"race-top\"><button class=\"back-games\" id=\"backRace\" type=\"button\">← All games</button><strong>Classroom Car Race</strong><span id=\"raceConnection\">Online</span></div>\n        <div class=\"race-join\" id=\"raceJoin\">\n          <div class=\"race-intro\"><span class=\"race-flag\">🏁</span><h2>Race your classmates</h2><p>Everyone types the same Karen passage. Accurate typing moves your car toward the finish line.</p></div>\n          <div class=\"race-options\">\n            <form class=\"race-option\" id=\"createRaceForm\"><strong>Teacher</strong><p>Create a room and share its code.</p><button class=\"button primary\" type=\"submit\">Create a race</button></form>\n            <form class=\"race-option\" id=\"joinRaceForm\"><strong>Student</strong><p>Enter the shared code and your name.</p><label>Room code<input id=\"raceCodeInput\" maxlength=\"5\" autocomplete=\"off\" placeholder=\"ABCDE\" required /></label><label>Your name<input id=\"raceNameInput\" maxlength=\"24\" autocomplete=\"name\" placeholder=\"Student name\" required /></label><button class=\"button primary\" type=\"submit\">Join race</button></form>\n          </div>\n          <p class=\"race-error\" id=\"raceError\" role=\"alert\"></p>\n        </div>\n        <div class=\"race-lobby\" id=\"raceLobby\" hidden>\n          <div class=\"room-code-card\"><span>ROOM CODE</span><strong id=\"roomCode\">—</strong><button class=\"button ghost\" id=\"copyRaceCode\" type=\"button\">Copy code</button></div>\n          <div class=\"lobby-copy\"><h2 id=\"lobbyTitle\">Waiting for racers</h2><p id=\"lobbyHint\">Students enter this code and their names.</p><button class=\"button primary\" id=\"startRace\" type=\"button\" hidden>Start race</button></div>\n          <div class=\"player-chips\" id=\"lobbyPlayers\"></div>\n        </div>\n        <div class=\"race-live\" id=\"raceLive\" hidden>\n          <div class=\"race-status\"><span id=\"raceStatusText\">Race in progress</span><strong id=\"racePosition\">—</strong></div>\n          <div class=\"race-track\" id=\"raceTrack\"></div>\n          <div class=\"race-passage\" id=\"racePassage\" lang=\"ksw\"></div>\n          <p class=\"race-prompt\" id=\"racePrompt\">Start typing with your English keyboard.</p>\n          <div class=\"race-keyboard keyboard\" id=\"raceKeyboard\"></div>\n        </div>\n      </section>\n      <p class=\"privacy\"><span aria-hidden=\"true\">●</span> Race rooms expire after four hours.</p>\n    </section>\n\n    <section class=\"workspace practice-view\" id=\"practiceView\" aria-labelledby=\"practice-title\" hidden>\n      <div class=\"practice-head\">\n        <div><p class=\"eyebrow\">KAREN TYPING PRACTICE</p><h1 id=\"practice-title\">Learn one key at a time</h1></div>\n        <label class=\"lesson-picker\">Lesson\n          <select id=\"lessonSelect\" aria-label=\"Choose a typing lesson\"></select>\n        </label>\n      </div>\n\n      <div class=\"stats-grid\" aria-label=\"Practice statistics\">\n        <div><strong id=\"progressStat\">0%</strong><span>Progress</span></div>\n        <div><strong id=\"accuracyStat\">100%</strong><span>Accuracy</span></div>\n        <div><strong id=\"wpmStat\">0</strong><span>WPM</span></div>\n      </div>\n\n      <div class=\"lesson-card\">\n        <div class=\"lesson-meta\"><span id=\"lessonNumber\">Lesson 1</span><span id=\"lessonFocus\">Basic letters</span></div>\n        <div class=\"progress-track\"><span id=\"progressBar\"></span></div>\n        <div class=\"target-text\" id=\"targetText\" lang=\"ksw\" aria-live=\"polite\" style=\"color:#17233b;position:relative\"></div>\n        <p class=\"type-prompt\" id=\"typePrompt\">Start typing with your English keyboard.</p>\n        <div class=\"lesson-actions\">\n          <button class=\"button ghost\" id=\"restartLesson\" type=\"button\">↻ Restart</button>\n          <button class=\"button primary\" id=\"nextLesson\" type=\"button\" hidden>Next lesson →</button>\n        </div>\n      </div>\n\n      <section class=\"keyboard-card practice-keyboard-card\" aria-label=\"Practice keyboard\">\n        <div class=\"keyboard-top\">\n          <div class=\"mode-switch\" role=\"group\" aria-label=\"Practice keyboard layer\">\n            <button class=\"active\" id=\"practiceNormal\" type=\"button\">Normal</button>\n            <button id=\"practiceShift\" type=\"button\">Shift</button>\n          </div>\n          <span class=\"next-key-label\">Next key: <strong id=\"nextKey\">—</strong></span>\n        </div>\n        <div class=\"keyboard\" id=\"practiceKeyboard\"></div>\n      </section>\n      <p class=\"privacy\"><span aria-hidden=\"true\">●</span> Practice progress is saved on this device.</p>\n    </section>\n  </main>\n  <div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\">Copied to clipboard</div>\n  <script src=\"app.js\"></script>\n  <script src=\"practice.js\"></script>\n  <script src=\"games.js\"></script>\n  <script src=\"race.js\"></script>\n</body>\n</html>\n","type":"text/html; charset=UTF-8"},"/styles.css":{"body":":root{--navy:#12213f;--blue:#2563eb;--cyan:#0ea5c6;--ink:#162033;--muted:#6b7280;--line:#dbe3ef;--paper:#fff;--bg:#edf3f9;--key:#f8fafc;--danger:#b42318;--shadow:0 18px 50px rgba(18,33,63,.10)}*{box-sizing:border-box}html{font-size:16px}body{margin:0;background:radial-gradient(circle at 85% 5%,#dceaff 0,transparent 28%),var(--bg);color:var(--ink);font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,\"Segoe UI\",\"Noto Sans Myanmar\",sans-serif;min-height:100vh}.app-shell{min-height:100vh}.topbar{height:78px;background:var(--navy);color:white;display:flex;align-items:center;justify-content:space-between;padding:0 max(24px,calc((100vw - 1180px)/2));box-shadow:0 5px 20px rgba(8,18,38,.2)}.brand{display:flex;align-items:center;gap:12px;color:inherit;text-decoration:none}.brand-mark{width:44px;height:44px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.35);border-radius:12px;background:linear-gradient(145deg,#1e3a6d,#142548);font-size:1.55rem;font-weight:700}.brand-logo{width:50px;height:50px;object-fit:cover;border-radius:50%;border:2px solid rgba(255,255,255,.8);background:white;box-shadow:0 3px 12px rgba(0,0,0,.2)}.brand strong,.brand small{display:block}.brand strong{font-size:1.05rem;letter-spacing:.01em}.brand small{font-size:.75rem;color:#a9b9d4;margin-top:2px}.status{display:flex;align-items:center;gap:8px;color:#cbd5e1;font-size:.85rem}.status span{width:8px;height:8px;border-radius:50%;background:#37d69a;box-shadow:0 0 0 4px rgba(55,214,154,.12)}.workspace{max-width:1180px;margin:0 auto;padding:48px 24px 36px}.workspace-heading{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:18px}.eyebrow{color:var(--cyan);font-size:.75rem;font-weight:800;letter-spacing:.16em;margin:0 0 5px}.workspace h1{font-size:clamp(1.75rem,4vw,2.6rem);letter-spacing:-.04em;line-height:1;margin:0}.hint{color:var(--muted);font-size:.9rem;margin:0 0 4px}.editor-card,.keyboard-card{background:var(--paper);border:1px solid rgba(203,213,225,.85);border-radius:18px;box-shadow:var(--shadow);overflow:hidden}.editor-card{margin-bottom:22px}textarea{width:100%;min-height:245px;resize:vertical;border:0;outline:0;padding:26px 28px;font-family:\"Noto Sans Myanmar\",\"Myanmar Text\",Padauk,sans-serif;font-size:1.65rem;line-height:1.8;color:#111827;background:white}textarea::placeholder{color:#aab3c0}.editor-footer{border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 14px 12px 20px;background:#fbfdff}.editor-footer>span{font-size:.82rem;color:var(--muted)}.actions{display:flex;gap:8px;align-items:center}.button{border:0;border-radius:9px;min-height:40px;padding:0 14px;font:inherit;font-size:.86rem;font-weight:700;cursor:pointer;transition:.16s transform,.16s background,.16s box-shadow}.button:active{transform:translateY(1px)}.ghost{background:#eef3f8;color:#364152}.ghost:hover{background:#e2e8f0}.danger{color:var(--danger);background:#fff0ee}.danger:hover{background:#ffe4e1}.primary{color:white;background:linear-gradient(135deg,#2563eb,#1687d6);box-shadow:0 6px 14px rgba(37,99,235,.22)}.primary:hover{box-shadow:0 8px 18px rgba(37,99,235,.3)}.keyboard-card{padding:18px}.keyboard-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.mode-switch{display:flex;background:#edf2f7;padding:4px;border-radius:10px}.mode-switch button,.layout-note{font:inherit;border:0;cursor:pointer}.mode-switch button{font-size:.8rem;font-weight:700;padding:7px 13px;border-radius:7px;color:#64748b;background:transparent}.mode-switch .active{color:#173868;background:white;box-shadow:0 2px 7px rgba(15,23,42,.12)}.layout-note{background:transparent;color:#64748b;font-size:.8rem}.guide{padding:10px 12px;background:#eff8ff;color:#34506c;border-radius:9px;font-size:.82rem;margin:-6px 0 14px}.keyboard{display:flex;flex-direction:column;gap:8px;overflow-x:auto;padding-bottom:2px}.key-row{display:flex;justify-content:center;gap:7px;min-width:740px}.key{position:relative;min-width:62px;height:60px;flex:1;max-width:86px;border:1px solid #cbd5e1;border-bottom-width:3px;border-radius:10px;background:linear-gradient(#fff,#f3f6fa);color:#13203a;cursor:pointer;font-family:\"Noto Sans Myanmar\",\"Myanmar Text\",Padauk,sans-serif;font-size:1.5rem;font-weight:600;box-shadow:0 2px 4px rgba(15,23,42,.05);transition:.1s}.key:hover{border-color:#8da4c0;background:#f5f9ff}.key:active,.key.pressed{transform:translateY(2px);border-bottom-width:1px;background:#e8f2ff}.key small{position:absolute;top:4px;left:7px;color:#7b8797;font:600 .62rem Inter,ui-sans-serif,sans-serif}.key.wide{max-width:140px;flex:1.6;font-family:Inter,ui-sans-serif,sans-serif;font-size:.8rem;color:#526075}.key.space{max-width:430px;flex:5}.privacy{text-align:center;color:#778396;font-size:.78rem;margin:20px 0 0}.privacy span{color:#25b681;margin-right:5px}.toast{position:fixed;left:50%;bottom:24px;transform:translate(-50%,20px);padding:12px 18px;border-radius:10px;background:#12213f;color:white;opacity:0;pointer-events:none;transition:.25s;box-shadow:0 10px 30px rgba(0,0,0,.2);font-size:.88rem}.toast.show{opacity:1;transform:translate(-50%,0)}@media(max-width:720px){.brand-logo{width:44px;height:44px}.brand strong{font-size:.9rem}.topbar{height:68px;padding:0 18px}.status{display:none}.workspace{padding:30px 14px 28px}.workspace-heading{display:block}.hint{margin-top:9px}.editor-footer{align-items:flex-start;padding:12px;flex-direction:column}.actions{width:100%;display:grid;grid-template-columns:repeat(3,1fr)}.actions .primary{grid-column:span 3}.actions #undo{display:none}textarea{min-height:220px;padding:20px;font-size:1.45rem}.keyboard-card{padding:14px 10px}.key-row{justify-content:flex-start;min-width:680px}.key{min-width:55px;height:56px}.button{padding:0 8px}.keyboard-top{padding:0 4px}.layout-note{font-size:.75rem}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}\nbody::before,body::after{content:\"\";position:fixed;top:78px;bottom:0;width:clamp(150px,18vw,260px);background:url(\"logo.png\") center/contain no-repeat;opacity:.09;pointer-events:none;z-index:0}body::before{left:18px}body::after{right:18px}.app-shell{position:relative;z-index:1}@media(max-width:900px){body::before,body::after{display:none}}\n","type":"text/css; charset=UTF-8"},"/padauk.css":{"body":"@import url('https://fonts.googleapis.com/css2?family=Padauk:wght@400;700&display=swap');\n\n[lang=\"ksw\"], textarea, .key, .brand-mark, .brand small, .eyebrow {\n  font-family: \"Padauk\", \"Noto Sans Myanmar\", \"Myanmar Text\", sans-serif;\n  font-language-override: \"ksw\";\n}\n","type":"text/css; charset=UTF-8"},"/practice.css":{"body":".topnav{display:flex;align-items:center;gap:5px;background:rgba(255,255,255,.08);padding:4px;border-radius:11px}.topnav button{border:0;background:transparent;color:#b9c7dd;font:700 .86rem Inter,ui-sans-serif,sans-serif;padding:8px 16px;border-radius:8px;cursor:pointer}.topnav button.active{background:white;color:#173868;box-shadow:0 3px 10px rgba(0,0,0,.15)}.practice-view[hidden]{display:none}.practice-head{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:20px}.practice-head h1{font-size:clamp(1.75rem,4vw,2.6rem);letter-spacing:-.04em;line-height:1.05;margin:0}.lesson-picker{display:flex;align-items:center;gap:10px;color:#68758a;font-size:.85rem;font-weight:700}.lesson-picker select{min-width:190px;border:1px solid #cbd5e1;border-radius:9px;padding:10px 34px 10px 12px;background:white;color:#24324a;font:700 .86rem Inter,ui-sans-serif,sans-serif}.stats-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:16px}.stats-grid div{background:white;border:1px solid #dbe3ef;border-radius:13px;padding:14px 18px;box-shadow:0 8px 22px rgba(18,33,63,.05);display:flex;align-items:baseline;justify-content:space-between}.stats-grid strong{font-size:1.45rem;color:#173868}.stats-grid span{font-size:.78rem;color:#748095;font-weight:700}.lesson-card{background:white;border:1px solid #dbe3ef;border-radius:18px;box-shadow:0 18px 50px rgba(18,33,63,.10);padding:22px 26px 20px;margin-bottom:20px}.lesson-meta{display:flex;justify-content:space-between;gap:10px;color:#6b7280;font-size:.78rem;font-weight:800;text-transform:uppercase;letter-spacing:.06em}.lesson-meta span:first-child{color:#0e91ad}.progress-track{height:7px;background:#e8eef5;border-radius:99px;overflow:hidden;margin:13px 0 26px}.progress-track span{display:block;width:0;height:100%;background:linear-gradient(90deg,#0ea5c6,#2563eb);border-radius:inherit;transition:width .18s}.target-text{min-height:112px;padding:18px 8px;font-family:\"Padauk\",\"Noto Sans Myanmar\",sans-serif;font-language-override:\"ksw\";font-size:clamp(1.65rem,4vw,2.25rem);line-height:1.9;letter-spacing:.015em;color:#aab3c0;word-break:break-word}.target-text .done{color:#1f9b72}.target-text .current{color:#17233b;background:#dcecff;border-bottom:3px solid #2563eb;border-radius:4px;padding:0 2px}.target-text .pending{color:#9da8b7}.type-prompt{text-align:center;color:#748095;font-size:.86rem;margin:8px 0 14px}.type-prompt.error{color:#b42318}.type-prompt.complete{color:#15815f;font-weight:800}.lesson-actions{display:flex;justify-content:center;gap:10px}.practice-keyboard-card .key.expected{border-color:#2563eb;background:#dcecff;box-shadow:0 0 0 3px rgba(37,99,235,.16);color:#0e3d94}.practice-keyboard-card .key.wrong{border-color:#d92d20;background:#fff0ee}.next-key-label{color:#6b7280;font-size:.82rem}.next-key-label strong{display:inline-grid;place-items:center;min-width:31px;height:30px;margin-left:4px;border-radius:7px;background:#e7f0ff;color:#174ba7;font:700 1.1rem \"Padauk\",sans-serif}@media(max-width:720px){.brand small{display:none}.brand-mark{width:38px;height:38px}.topnav button{padding:7px 11px}.practice-head{display:block}.lesson-picker{margin-top:16px;justify-content:space-between}.lesson-picker select{min-width:0;flex:1}.stats-grid{gap:7px}.stats-grid div{padding:11px 9px;display:block;text-align:center}.stats-grid strong,.stats-grid span{display:block}.stats-grid strong{font-size:1.2rem}.lesson-card{padding:18px 14px}.target-text{min-height:120px;padding:12px 2px}.practice-keyboard-card{overflow:hidden}}\n","type":"text/css; charset=UTF-8"},"/games.css":{"body":".games-view[hidden],.game-stage[hidden]{display:none}.games-heading{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:22px}.games-heading h1{font-size:clamp(1.75rem,4vw,2.6rem);letter-spacing:-.04em;line-height:1;margin:0}.game-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.game-card{min-height:250px;border:1px solid #dbe3ef;border-radius:18px;background:white;padding:24px;text-align:left;display:flex;flex-direction:column;align-items:flex-start;cursor:pointer;box-shadow:0 15px 38px rgba(18,33,63,.08);transition:.18s transform,.18s box-shadow;font:inherit;color:#17233b}.game-card:hover{transform:translateY(-4px);box-shadow:0 22px 48px rgba(18,33,63,.14)}.game-card .game-icon{width:56px;height:56px;border-radius:16px;display:grid;place-items:center;font-size:1.65rem;margin-bottom:28px}.sprint-card .game-icon{background:#fff1cf;color:#bd6700}.rain-card .game-icon{background:#ddf4ff;color:#087a9f}.match-card .game-icon{background:#e9e4ff;color:#6545b8}.game-card strong,.game-card small{display:block}.game-card strong{font-size:1.25rem;margin-bottom:8px}.game-card small{font-size:.86rem;line-height:1.55;color:#6f7b8d}.game-card em{font-style:normal;font-size:.84rem;font-weight:800;color:#2563eb;margin-top:auto;padding-top:22px}.game-stage{background:white;border:1px solid #dbe3ef;border-radius:18px;box-shadow:0 18px 50px rgba(18,33,63,.1);overflow:hidden}.game-stage-top{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:13px 16px;border-bottom:1px solid #e2e8f0}.game-stage-top>strong{text-align:center}.game-stage-top .button{justify-self:end}.back-games{border:0;background:transparent;color:#526075;font:700 .83rem Inter,sans-serif;cursor:pointer;justify-self:start}.game-stats{display:grid;grid-template-columns:repeat(3,1fr);border-bottom:1px solid #e2e8f0;background:#f8fbff}.game-stats div{text-align:center;padding:12px;border-right:1px solid #e2e8f0}.game-stats div:last-child{border:0}.game-stats span,.game-stats strong{display:block}.game-stats span{font-size:.7rem;text-transform:uppercase;letter-spacing:.08em;color:#7b8797;font-weight:800}.game-stats strong{font-size:1.35rem;color:#173868}.playfield{position:relative;min-height:300px;overflow:hidden;background:radial-gradient(circle at 50% 0,#eef6ff,transparent 58%),#fbfdff}.game-message{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;z-index:4;background:rgba(251,253,255,.92)}.game-message[hidden]{display:none}.game-message strong{font-size:1.65rem;margin-bottom:5px}.game-message span{color:#748095;margin-bottom:20px}.word-challenge{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center}.word-challenge[hidden]{display:none}.challenge-label{font:800 .7rem Inter,sans-serif;letter-spacing:.12em;color:#7b8797}.word-challenge>strong{font:700 clamp(2.2rem,7vw,4.2rem) \"Padauk\",sans-serif;color:#17233b;line-height:1.5}.typed-answer{min-height:46px;font:700 1.65rem \"Padauk\",sans-serif;color:#1f9b72;border-bottom:3px solid #cbd5e1;min-width:160px;text-align:center}.typed-answer.wrong{color:#d92d20;border-color:#d92d20}.falling-word{position:absolute;left:50%;top:12px;transform:translateX(-50%);padding:9px 18px;border-radius:12px;background:white;border:2px solid #4ba7d1;box-shadow:0 8px 24px rgba(20,93,126,.18);font:700 2rem \"Padauk\",sans-serif;color:#173868;white-space:nowrap}.game-tip{text-align:center;color:#748095;font-size:.82rem;margin:13px}.game-keyboard{padding:0 14px 18px;overflow-x:auto}.game-keyboard .key-row{min-width:680px}.game-keyboard .key{height:50px;min-width:52px;font-size:1.25rem}.game-keyboard .key.expected{border-color:#2563eb;background:#dcecff;box-shadow:0 0 0 3px rgba(37,99,235,.15)}.game-keyboard .key.space{font:700 .8rem Inter,sans-serif}@media(max-width:800px){.game-grid{grid-template-columns:1fr}.game-card{min-height:185px}.game-card .game-icon{margin-bottom:18px}.games-heading{display:block}.games-heading .hint{margin-top:10px}.game-stage-top{grid-template-columns:1fr 1fr}.game-stage-top>strong{display:none}.playfield{min-height:270px}.topnav button{padding-left:9px;padding-right:9px}}\n","type":"text/css; charset=UTF-8"},"/race.css":{"body":".race-stage[hidden],.race-join[hidden],.race-lobby[hidden],.race-live[hidden]{display:none}.race-card{grid-column:span 2;background:linear-gradient(135deg,#10274d,#184b78);color:#fff;border-color:#275c89}.race-card small{color:#cfe5f5}.race-card em{color:#80e4bc}.race-card .game-icon{background:#e8fff5;color:#107453}.race-stage{background:#fff;border:1px solid #dbe3ef;border-radius:18px;overflow:hidden;box-shadow:0 18px 50px rgba(18,33,63,.1)}.race-top{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:14px 18px;border-bottom:1px solid #e2e8f0}.race-top>strong{text-align:center}.race-top>span{justify-self:end;font-size:.78rem;font-weight:800;color:#15805f}.race-join{padding:30px}.race-intro{text-align:center;max-width:560px;margin:0 auto 25px}.race-flag{display:block;font-size:2.7rem}.race-intro h2{font-size:1.8rem;margin:4px 0 7px;color:#17233b}.race-intro p,.race-option p,.lobby-copy p{color:#6f7b8d;line-height:1.55}.race-options{display:grid;grid-template-columns:1fr 1fr;gap:18px;max-width:780px;margin:auto}.race-option{border:1px solid #dbe3ef;border-radius:16px;padding:22px;background:#f8fbff}.race-option>strong{font-size:1.2rem;color:#173868}.race-option label{display:block;font-size:.8rem;font-weight:800;color:#526075;margin:12px 0}.race-option input{display:block;width:100%;box-sizing:border-box;margin-top:5px;border:1px solid #cbd5e1;border-radius:10px;padding:11px 12px;font:600 1rem Inter,sans-serif;text-transform:none}.race-option #raceCodeInput{text-transform:uppercase;letter-spacing:.18em}.race-option .button{width:100%;justify-content:center;margin-top:8px}.race-error{min-height:22px;text-align:center;color:#c92525;font-weight:700}.race-lobby{padding:28px}.room-code-card{text-align:center;border:2px dashed #76a8ca;border-radius:18px;background:#eef8ff;padding:22px;max-width:420px;margin:0 auto}.room-code-card span,.room-code-card strong{display:block}.room-code-card span{font-size:.72rem;font-weight:900;letter-spacing:.13em;color:#628096}.room-code-card strong{font:900 2.8rem Inter,sans-serif;letter-spacing:.2em;color:#173868;margin:4px 0 12px}.lobby-copy{text-align:center;margin:22px auto;max-width:600px}.lobby-copy h2{margin-bottom:5px}.player-chips{display:flex;justify-content:center;gap:9px;flex-wrap:wrap}.player-chips span{padding:8px 13px;border-radius:999px;background:#e9f8f2;color:#14654c;font-weight:800}.race-status{display:flex;justify-content:space-between;align-items:center;padding:13px 20px;background:#10274d;color:#fff}.race-status strong{color:#82e9bf}.race-track{padding:16px 18px;background:#d8ecf6}.race-lane{position:relative;height:58px;border-bottom:3px dashed rgba(255,255,255,.9);margin-bottom:8px}.race-lane:last-child{margin:0}.race-lane-name{position:absolute;left:0;top:2px;font-size:.75rem;font-weight:900;color:#173868;max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.race-car{position:absolute;left:4px;bottom:6px;font-size:2rem;transform:translateX(0);transition:transform .45s ease;filter:drop-shadow(0 4px 3px rgba(20,40,60,.18))}.race-finish{position:absolute;right:2px;inset-block:0;width:12px;background:repeating-conic-gradient(#17233b 0 25%,white 0 50%) 0/12px 12px}.race-passage{padding:24px 22px 10px;font:700 clamp(1.7rem,4vw,2.5rem)/1.8 \"Padauk\",sans-serif;text-align:center;color:#17233b}.race-passage .done{color:#15956d;background:#dff8ef}.race-passage .current{background:#ffe48b;border-radius:4px}.race-prompt{text-align:center;color:#6f7b8d;margin:0 0 10px}.race-keyboard{padding:4px 14px 20px;overflow-x:auto}.race-keyboard .key-row{min-width:680px}.race-keyboard .key{height:48px;min-width:52px}.race-keyboard .key.expected{border-color:#f0b429;background:#fff1b8;box-shadow:0 0 0 3px rgba(240,180,41,.18)}@media(max-width:800px){.race-card{grid-column:auto}.race-options{grid-template-columns:1fr}.race-join{padding:20px 14px}.race-top{grid-template-columns:1fr 1fr}.race-top>strong{display:none}.room-code-card strong{font-size:2.2rem}.race-lobby{padding:20px 14px}.race-car{font-size:1.65rem}}\n","type":"text/css; charset=UTF-8"},"/app.js":{"body":"const editor=document.querySelector('#editor');const keyboard=document.querySelector('#keyboard');const count=document.querySelector('#count');const toast=document.querySelector('#toast');let shifted=false;\n// KarenKNU S'gaw Karen Unicode map: [English key, normal, shifted].\nconst rows=[\n[['`','ပ','ြု'],['1','၁','ည'],['2','၂','ၥ'],['3','၃','£'],['4','၄','၃'],['5','၅','ရ'],['6','၆','၄'],['7','၇','ရ'],['8','၈','ဂ'],['9','၉','('],['0','ဝ',')'],['-','ြ','ြ'],['=','—','ှု']],\n[['q','ဆ','ခ'],['w','တ','တ'],['e','န','န'],['r','မ','ၤ'],['t','အ','၎'],['y','ပ','၌'],['u','က','ၢ'],['i','င','ၢ်'],['o','သ','ၣ်'],['p','စ','ာ်'],['[','ဟ','ဧ'],[']','=','ဂ'],['\\\\','ၪ','ၑ']],\n[['a','ေ','∕'],['s','ျ','ှ'],['d','ိ','ီ'],['f','်','ၠ'],['g','ါ','ွ'],['h','့','ံ'],['j','ြ','ဲ'],['k','ု','ု'],['l','ူ','ူ'],[';','း','ၤ'],[\"'\",'ဒ','ီ']],\n[['z','ဖ','ဇ'],['x','ထ','ဌ'],['c','ခ','ဃ'],['v','လ','ျ့'],['b','ဘ','ြ'],['n','ည','ဒ'],['m','ာ်','ျ့'],[',','ယ',','],['.','ၣ်','ၢ်'],['/','”','“']]\n];\nconst special=[['Backspace','Backspace','⌫'],[' ','Space','Space'],['Enter','Enter','↵ Enter']];\nfunction render(){keyboard.innerHTML='';rows.forEach(row=>{const el=document.createElement('div');el.className='key-row';row.forEach(([latin,normal,shift])=>el.appendChild(makeKey(latin,shifted?shift:normal)));keyboard.appendChild(el)});const bottom=document.createElement('div');bottom.className='key-row';special.forEach(([value,label,display])=>{const b=makeKey(label,display,value);b.classList.add('wide');if(value===' ')b.classList.add('space');bottom.appendChild(b)});keyboard.appendChild(bottom)}\nfunction makeKey(label,char,value=char){const b=document.createElement('button');b.type='button';b.className='key';b.dataset.value=value;b.dataset.code=label;b.innerHTML=`<small>${label==='Space'?'':label}</small>${char}`;b.addEventListener('click',()=>insert(value));return b}\nfunction insert(value){editor.focus();if(value==='Backspace'){document.execCommand('delete');}else if(value==='Enter'){document.execCommand('insertText',false,'\\n');}else{document.execCommand('insertText',false,value)}updateCount()}\nfunction updateCount(){const n=[...editor.value].length;count.textContent=`${n} ${n===1?'character':'characters'}`}\nfunction setShift(on){shifted=on;document.querySelector('#normalMode').classList.toggle('active',!on);document.querySelector('#shiftMode').classList.toggle('active',on);render()}\ndocument.querySelector('#normalMode').onclick=()=>setShift(false);document.querySelector('#shiftMode').onclick=()=>setShift(true);\nfunction physicalKey(e){if(e.code.startsWith('Key'))return e.code.slice(3).toLowerCase();if(e.code.startsWith('Digit'))return e.code.slice(5);return({Backquote:'`',Minus:'-',Equal:'=',BracketLeft:'[',BracketRight:']',Backslash:'\\\\',Semicolon:';',Quote:\"'\",Comma:',',Period:'.',Slash:'/'}[e.code]||e.key.toLowerCase())}\neditor.addEventListener('input',updateCount);editor.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='Shift'){setShift(true);return}const key=physicalKey(e);const match=rows.flat().find(([mapped])=>mapped===key);if(match){e.preventDefault();insert(e.shiftKey?match[2]:match[1]);flashKey(match[0])}});editor.addEventListener('keyup',e=>{if(e.key==='Shift')setShift(false)});\nfunction flashKey(code){const b=[...document.querySelectorAll('.key')].find(k=>k.dataset.code===code);if(b){b.classList.add('pressed');setTimeout(()=>b.classList.remove('pressed'),110)}}\ndocument.querySelector('#copy').onclick=async()=>{if(!editor.value){showToast('Type something first');return}try{await navigator.clipboard.writeText(editor.value)}catch{editor.select();document.execCommand('copy')}document.querySelector('#copyText').textContent='Copied';showToast('Copied to clipboard');setTimeout(()=>document.querySelector('#copyText').textContent='Copy text',1400)};\ndocument.querySelector('#clear').onclick=()=>{if(!editor.value)return;editor.value='';updateCount();editor.focus();showToast('Text cleared')};document.querySelector('#selectAll').onclick=()=>{editor.focus();editor.select()};document.querySelector('#undo').onclick=()=>{editor.focus();document.execCommand('undo');updateCount()};document.querySelector('#toggleGuide').onclick=()=>{const g=document.querySelector('#guide');g.hidden=!g.hidden};\nfunction showToast(message){toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1600)}render();updateCount();\n","type":"text/javascript; charset=UTF-8"},"/practice.js":{"body":"const lessons=[\n  {title:'Basic letters',focus:'ဆ တ န မ အ ပ က င သ စ',text:'ဆ တ န မ အ ပ က င သ စ ဆ တ န မ အ ပ က င သ စ'},\n  {title:'Vowels and marks',focus:'ါ ိ ု ူ ေ ဲ ၢ ၣ် ၤ',text:'ါ ိ ု ူ ေ ဲ ၢ ၣ် ၤ ါ ိ ု ူ ေ ဲ ၢ ၣ် ၤ'},\n  {title:'Family words',focus:'ဟံၣ်ဖိဃီဖိ',text:'ဟံၣ်ဖိဃီဖိ မိၢ် ပၢ် မိၢ်ပၢ် ဖိခွါ ဖိမုၣ်'},\n  {title:'Days of the week',focus:'မုၢ်ဒဲး',text:'မုၢ်ဒဲး မုၢ်ဆၣ် မုၢ်ယူာ် မုၢ်ပျဲၤ မုၢ်လ့ဧိၤ'},\n  {title:'Food words',focus:'တၢ်အီၣ်',text:'တၢ်အီၣ် မ့ၤ ညၣ် ဆီညၣ် ထိးညၣ် ကျီၢ်ညၣ်'},\n  {title:'Time expressions',focus:'ကိးနံၤဒဲး',text:'ကိးနံၤဒဲး ကိးဂီၤဒဲး ကိးဟါဒဲး ကိးနၤဒဲး ကိးနွံဒဲး'}\n];\nconst typeView=document.querySelector('#typeView'),practiceView=document.querySelector('#practiceView'),navType=document.querySelector('#navType'),navPractice=document.querySelector('#navPractice');\nconst lessonSelect=document.querySelector('#lessonSelect'),targetText=document.querySelector('#targetText'),practiceKeyboard=document.querySelector('#practiceKeyboard');\nlet lessonIndex=Number(localStorage.getItem('karenLesson')||0);if(lessonIndex>=lessons.length)lessonIndex=0;let position=0,attempts=0,errors=0,startTime=0,practiceShifted=false,chunks=[];\nlessons.forEach((lesson,i)=>{const option=document.createElement('option');option.value=i;option.textContent=`${i+1}. ${lesson.title}`;lessonSelect.appendChild(option)});\nfunction showView(view){const practice=view==='practice';typeView.hidden=practice;practiceView.hidden=!practice;const games=document.querySelector('#gamesView');if(games)games.hidden=true;if(typeof closeRace==='function')closeRace();navType.classList.toggle('active',!practice);navPractice.classList.toggle('active',practice);const gamesNav=document.querySelector('#navGames');if(gamesNav)gamesNav.classList.remove('active');if(practice){renderLesson();setTimeout(()=>window.scrollTo({top:0,behavior:'smooth'}),0)}else editor.focus()}\nnavType.onclick=()=>showView('type');navPractice.onclick=()=>showView('practice');\nfunction allMappings(){return rows.flat().flatMap(([key,normal,shift])=>[{key,value:normal,shift:false},{key,value:shift,shift:true}]).sort((a,b)=>b.value.length-a.value.length)}\nfunction expectedMapping(){const target=lessons[lessonIndex].text;return allMappings().find(m=>target.startsWith(m.value,position))||({key:'Space',value:' ',shift:false})}\nfunction renderLesson(){const lesson=lessons[lessonIndex];lessonSelect.value=lessonIndex;document.querySelector('#lessonNumber').textContent=`Lesson ${lessonIndex+1}`;document.querySelector('#lessonFocus').textContent=lesson.title;renderTarget();renderPracticeKeyboard();updateStats()}\nfunction drawTypedHighlight(){targetText.querySelectorAll('.typed-progress').forEach(el=>el.remove());if(!position||!targetText.firstChild)return;const range=document.createRange();range.setStart(targetText.firstChild,0);range.setEnd(targetText.firstChild,Math.min(position,targetText.firstChild.length));const parent=targetText.getBoundingClientRect();[...range.getClientRects()].forEach(rect=>{if(!rect.width)return;const mark=document.createElement('span');mark.className='typed-progress';mark.setAttribute('aria-hidden','true');Object.assign(mark.style,{position:'absolute',pointerEvents:'none',left:`${rect.left-parent.left}px`,top:`${rect.top-parent.top}px`,width:`${rect.width}px`,height:`${rect.height}px`,background:'rgba(31,155,114,.18)',borderBottom:'3px solid #1f9b72',borderRadius:'4px'});targetText.appendChild(mark)})}\nfunction renderTarget(){const text=lessons[lessonIndex].text;const expected=expectedMapping();targetText.textContent=text;requestAnimationFrame(drawTypedHighlight);if(document.fonts)document.fonts.ready.then(drawTypedHighlight);const label=document.querySelector('#nextKey');label.textContent=position>=text.length?'✓':expected.shift?`⇧ ${expected.key}`:expected.key==='Space'?'␣':expected.key;document.querySelector('#typePrompt').textContent=position>=text.length?'Lesson complete!':'Start typing with your English keyboard.';document.querySelector('#typePrompt').className=position>=text.length?'type-prompt complete':'type-prompt';document.querySelector('#nextLesson').hidden=position<text.length}\nfunction renderPracticeKeyboard(){practiceKeyboard.innerHTML='';rows.forEach(row=>{const el=document.createElement('div');el.className='key-row';row.forEach(([key,normal,shift])=>{const b=document.createElement('button');b.type='button';b.className='key';b.dataset.code=key;b.innerHTML=`<small>${key}</small>${practiceShifted?shift:normal}`;b.onclick=()=>handlePractice(practiceShifted?shift:normal);el.appendChild(b)});practiceKeyboard.appendChild(el)});const bottom=document.createElement('div');bottom.className='key-row';const space=document.createElement('button');space.type='button';space.className='key wide space';space.dataset.code='Space';space.textContent='Space';space.onclick=()=>handlePractice(' ');bottom.appendChild(space);practiceKeyboard.appendChild(bottom);highlightExpected()}\nfunction highlightExpected(){practiceKeyboard.querySelectorAll('.key').forEach(k=>k.classList.remove('expected'));if(position>=lessons[lessonIndex].text.length)return;const expected=expectedMapping();setPracticeShift(expected.shift);const key=practiceKeyboard.querySelector(`[data-code=\"${CSS.escape(expected.key)}\"]`);if(key)key.classList.add('expected')}\nfunction setPracticeShift(on){if(practiceShifted===on)return;practiceShifted=on;document.querySelector('#practiceNormal').classList.toggle('active',!on);document.querySelector('#practiceShift').classList.toggle('active',on);renderPracticeKeyboard()}\ndocument.querySelector('#practiceNormal').onclick=()=>setPracticeShift(false);document.querySelector('#practiceShift').onclick=()=>setPracticeShift(true);\nfunction handlePractice(value){const text=lessons[lessonIndex].text;if(position>=text.length)return;if(!startTime)startTime=Date.now();attempts++;if(text.startsWith(value,position)){chunks.push(value);position+=value.length;renderTarget();updateStats();highlightExpected();if(position>=text.length)localStorage.setItem('karenLesson',Math.min(lessonIndex+1,lessons.length-1))}else{errors++;const prompt=document.querySelector('#typePrompt');prompt.textContent='Try that key again.';prompt.className='type-prompt error';const expected=expectedMapping();const key=practiceKeyboard.querySelector(`[data-code=\"${CSS.escape(expected.key)}\"]`);if(key){key.classList.add('wrong');setTimeout(()=>key.classList.remove('wrong'),220)}updateStats()}}\nfunction updateStats(){const text=lessons[lessonIndex].text;const progress=Math.round(position/text.length*100);const accuracy=attempts?Math.max(0,Math.round((attempts-errors)/attempts*100)):100;const mins=startTime?Math.max((Date.now()-startTime)/60000,1/60):0;const typed=[...chunks.join('')].length;const wpm=mins?Math.round(typed/5/mins):0;document.querySelector('#progressStat').textContent=`${progress}%`;document.querySelector('#accuracyStat').textContent=`${accuracy}%`;document.querySelector('#wpmStat').textContent=wpm;document.querySelector('#progressBar').style.width=`${progress}%`}\nfunction resetLesson(){position=0;attempts=0;errors=0;startTime=0;chunks=[];renderLesson()}\nlessonSelect.onchange=()=>{lessonIndex=Number(lessonSelect.value);localStorage.setItem('karenLesson',lessonIndex);resetLesson()};document.querySelector('#restartLesson').onclick=resetLesson;document.querySelector('#nextLesson').onclick=()=>{lessonIndex=(lessonIndex+1)%lessons.length;localStorage.setItem('karenLesson',lessonIndex);resetLesson()};\ndocument.addEventListener('keydown',e=>{if(practiceView.hidden||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='Shift'){setPracticeShift(true);return}if(e.key==='Backspace'){e.preventDefault();if(chunks.length){const removed=chunks.pop();position-=removed.length;renderTarget();updateStats();highlightExpected()}return}if(e.key===' '){e.preventDefault();handlePractice(' ');return}const key=physicalKey(e);const match=rows.flat().find(([mapped])=>mapped===key);if(match){e.preventDefault();handlePractice(e.shiftKey?match[2]:match[1])}});document.addEventListener('keyup',e=>{if(!practiceView.hidden&&e.key==='Shift')highlightExpected()});\nwindow.addEventListener('resize',drawTypedHighlight);renderLesson();\n","type":"text/javascript; charset=UTF-8"},"/games.js":{"body":"const navGames=document.querySelector('#navGames'),gamesView=document.querySelector('#gamesView'),gameGrid=document.querySelector('#gameGrid'),gameStage=document.querySelector('#gameStage');\nconst gameWords=['မိၢ်','ပၢ်','မိၢ်ပၢ်','ဖိခွါ','ဖိမုၣ်','ဟံၣ်ဖိဃီဖိ','တၢ်အီၣ်','မ့ၤ','ညၣ်','ဆီညၣ်','မုၢ်ဒဲး','မုၢ်ဆၣ်','မုၢ်ယူာ်','ကိးနံၤဒဲး','ကိးဂီၤဒဲး','ကိးဟါဒဲး'];\nlet activeGame='',gameRunning=false,gameScore=0,gameStreak=0,gameSeconds=45,gameTarget='',gameBuffer='',gameTimer=null,fallFrame=null,fallStart=0,fallDuration=8000,matchRounds=0,matchTarget=null,lastWord='';\nfunction openGames(){typeView.hidden=true;practiceView.hidden=true;gamesView.hidden=false;navType.classList.remove('active');navPractice.classList.remove('active');navGames.classList.add('active');stopGame();if(typeof closeRace==='function')closeRace();gameGrid.hidden=false;gameStage.hidden=true;window.scrollTo({top:0,behavior:'smooth'})}\nnavGames.onclick=openGames;\nfunction chooseGame(name){if(name==='race'){openRace();return}activeGame=name;gameGrid.hidden=true;gameStage.hidden=false;const titles={sprint:'Word Sprint',rain:'Falling Words'};document.querySelector('#activeGameTitle').textContent=titles[name];resetGame()}\ngameGrid.querySelectorAll('[data-game]').forEach(card=>card.onclick=()=>chooseGame(card.dataset.game));document.querySelector('#backGames').onclick=()=>{stopGame();gameStage.hidden=true;gameGrid.hidden=false};document.querySelector('#restartGame').onclick=resetGame;document.querySelector('#startGame').onclick=startGame;\nfunction resetGame(){stopGame();gameScore=0;gameStreak=0;gameSeconds=activeGame==='sprint'?45:activeGame==='rain'?3:10;matchRounds=0;matchTarget=null;gameBuffer='';updateGameStats();document.querySelector('#gameMessage').hidden=false;document.querySelector('#gameMessage').querySelector('strong').textContent='Ready?';document.querySelector('#gameMessage').querySelector('span').textContent=activeGame==='sprint'?'Type as many words as you can in 45 seconds.':activeGame==='rain'?'You have three lives. Do not let a word fall.':'Match ten Karen characters to their English keys.';document.querySelector('#startGame').textContent='Start game';document.querySelector('#wordChallenge').hidden=true;document.querySelector('#fallingWord').hidden=true;renderGameKeyboard()}\nfunction stopGame(){gameRunning=false;clearInterval(gameTimer);gameTimer=null;cancelAnimationFrame(fallFrame);fallFrame=null}\nfunction startGame(){stopGame();gameRunning=true;document.querySelector('#gameMessage').hidden=true;gameBuffer='';if(activeGame==='sprint'){gameSeconds=45;gameTimer=setInterval(()=>{gameSeconds--;updateGameStats();if(gameSeconds<=0)finishGame('Time is up!')},1000);nextWord()}else if(activeGame==='rain'){gameSeconds=3;nextFallingWord()}else{gameSeconds=10;nextMatch()}}\nfunction randomWord(){let word;do{word=gameWords[Math.floor(Math.random()*gameWords.length)]}while(word===lastWord&&gameWords.length>1);lastWord=word;return word}\nfunction nextWord(){gameTarget=randomWord();gameBuffer='';document.querySelector('#wordChallenge').hidden=false;document.querySelector('#challengeLabel').textContent='TYPE THIS WORD';document.querySelector('#challengeWord').textContent=gameTarget;document.querySelector('#typedAnswer').textContent='';document.querySelector('#typedAnswer').className='typed-answer';renderGameKeyboard()}\nfunction nextFallingWord(){gameTarget=randomWord();gameBuffer='';const falling=document.querySelector('#fallingWord');falling.textContent=gameTarget;falling.hidden=false;document.querySelector('#wordChallenge').hidden=false;document.querySelector('#challengeLabel').textContent='YOUR TYPING';document.querySelector('#challengeWord').textContent='';document.querySelector('#typedAnswer').textContent='';fallStart=performance.now();fallDuration=Math.max(3800,8000-gameScore*180);cancelAnimationFrame(fallFrame);fallFrame=requestAnimationFrame(animateFall);renderGameKeyboard()}\nfunction animateFall(now){if(!gameRunning||activeGame!=='rain')return;const field=document.querySelector('#playfield'),word=document.querySelector('#fallingWord');const progress=Math.min(1,(now-fallStart)/fallDuration);word.style.top=`${12+progress*(field.clientHeight-word.offsetHeight-24)}px`;if(progress>=1){gameSeconds--;gameStreak=0;updateGameStats();if(gameSeconds<=0){finishGame('No lives left!');return}nextFallingWord();return}fallFrame=requestAnimationFrame(animateFall)}\nfunction matchPool(){return rows.flat().flatMap(([key,normal,shift])=>[{key,value:normal,shift:false},{key,value:shift,shift:true}]).filter(item=>item.value&&item.value.length<=2&&/[က-႟]/u.test(item.value))}\nfunction nextMatch(){if(matchRounds>=10){finishGame('Challenge complete!');return}const pool=matchPool();matchTarget=pool[Math.floor(Math.random()*pool.length)];gameTarget=matchTarget.value;gameBuffer='';document.querySelector('#wordChallenge').hidden=false;document.querySelector('#challengeLabel').textContent='TYPE THE ENGLISH KEY FOR';document.querySelector('#challengeWord').textContent=gameTarget;document.querySelector('#typedAnswer').textContent=matchTarget.shift?'Shift + ?':'?';renderGameKeyboard()}\nfunction gameExpected(){if(activeGame==='match')return matchTarget;return allMappings().find(m=>gameTarget.startsWith(m.value,gameBuffer.length))||null}\nfunction renderGameKeyboard(){const box=document.querySelector('#gameKeyboard');box.innerHTML='';const expected=gameExpected();const shifted=expected?.shift||false;rows.slice(1).forEach(row=>{const line=document.createElement('div');line.className='key-row';row.forEach(([key,normal,shift])=>{const b=document.createElement('button');b.type='button';b.className='key';b.dataset.code=key;b.innerHTML=`<small>${key}</small>${shifted?shift:normal}`;if(activeGame!=='match'&&expected&&expected.key===key)b.classList.add('expected');b.onclick=()=>acceptGameInput(shifted?shift:normal,key,shifted);line.appendChild(b)});box.appendChild(line)});if(activeGame!=='match'){const line=document.createElement('div');line.className='key-row';const b=document.createElement('button');b.type='button';b.className='key wide space';b.textContent='Space';b.onclick=()=>acceptGameInput(' ','Space',false);line.appendChild(b);box.appendChild(line)}}\nfunction acceptGameInput(value,key,shifted){if(!gameRunning)return;if(activeGame==='match'){const valid=matchPool().some(item=>item.value===gameTarget&&item.key===key&&item.shift===shifted&&item.shift===matchTarget.shift);if(valid){gameScore++;gameStreak++;matchRounds++;gameSeconds=10-matchRounds;updateGameStats();nextMatch()}else{gameStreak=0;updateGameStats();flashWrong()}return}const next=gameTarget.slice(gameBuffer.length);if(next.startsWith(value)){gameBuffer+=value;document.querySelector('#typedAnswer').textContent=gameBuffer;document.querySelector('#typedAnswer').className='typed-answer';if(gameBuffer===gameTarget){gameScore++;gameStreak++;updateGameStats();if(activeGame==='rain'){cancelAnimationFrame(fallFrame);nextFallingWord()}else nextWord()}else renderGameKeyboard()}else{gameStreak=0;updateGameStats();flashWrong()}}\nfunction flashWrong(){const answer=document.querySelector('#typedAnswer');answer.classList.add('wrong');setTimeout(()=>answer.classList.remove('wrong'),220)}\nfunction updateGameStats(){document.querySelector('#gameScore').textContent=gameScore;document.querySelector('#gameMiddleLabel').textContent=activeGame==='rain'?'Streak':'Streak';document.querySelector('#gameMiddle').textContent=gameStreak;document.querySelector('#gameTimeLabel').textContent=activeGame==='rain'?'Lives':activeGame==='match'?'Rounds left':'Time';document.querySelector('#gameTime').textContent=gameSeconds}\nfunction finishGame(title){stopGame();document.querySelector('#gameMessage').hidden=false;document.querySelector('#gameMessage').querySelector('strong').textContent=title;document.querySelector('#gameMessage').querySelector('span').textContent=`Final score: ${gameScore}`;document.querySelector('#startGame').textContent='Play again';const bestKey=`karenBest_${activeGame}`;localStorage.setItem(bestKey,Math.max(gameScore,Number(localStorage.getItem(bestKey)||0)))}\ndocument.addEventListener('keydown',e=>{if(gamesView.hidden||!gameRunning||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='Shift')return;const key=physicalKey(e);const match=rows.flat().find(([mapped])=>mapped===key);if(match){e.preventDefault();acceptGameInput(e.shiftKey?match[2]:match[1],key,e.shiftKey)}});\n","type":"text/javascript; charset=UTF-8"},"/race.js":{"body":"const raceStage=document.querySelector('#raceStage'),raceJoin=document.querySelector('#raceJoin'),raceLobby=document.querySelector('#raceLobby'),raceLive=document.querySelector('#raceLive');\nlet raceCode='',raceHostToken='',racePlayerId='',racePlayerToken='',racePlayerName='',racePassageText='',raceTyped='',racePollTimer=null,raceSendTimer=null,raceStartedAt=0,raceCorrect=0,raceErrors=0,raceMode='';\nconst carColors=['🚗','🚙','🏎️','🚕','🚓','🚘'];\nfunction openRace(){stopGame();gameGrid.hidden=true;gameStage.hidden=true;raceStage.hidden=false;raceJoin.hidden=false;raceLobby.hidden=true;raceLive.hidden=true;document.querySelector('#raceError').textContent='';document.querySelector('#raceCodeInput').value='';document.querySelector('#raceNameInput').value=''}\nfunction closeRace(){clearInterval(racePollTimer);racePollTimer=null;clearTimeout(raceSendTimer);raceStage.hidden=true;raceCode='';raceHostToken='';racePlayerId='';racePlayerToken='';raceTyped='';raceMode=''}\ndocument.querySelector('#backRace').onclick=()=>{closeRace();gameGrid.hidden=false};\nasync function raceApi(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'The race could not connect.');return data}\nfunction raceError(message){document.querySelector('#raceError').textContent=message}\ndocument.querySelector('#createRaceForm').onsubmit=async e=>{e.preventDefault();raceError('');try{const data=await raceApi('/api/race/create',{method:'POST',body:'{}'});raceCode=data.code;raceHostToken=data.hostToken;raceMode='host';showRaceLobby(data);beginRacePolling()}catch(error){raceError(error.message)}};\ndocument.querySelector('#joinRaceForm').onsubmit=async e=>{e.preventDefault();raceError('');const code=document.querySelector('#raceCodeInput').value.trim().toUpperCase(),name=document.querySelector('#raceNameInput').value.trim();try{const data=await raceApi('/api/race/join',{method:'POST',body:JSON.stringify({code,name})});raceCode=code;racePlayerId=data.playerId;racePlayerToken=data.playerToken;racePlayerName=name;raceMode='player';showRaceLobby(data);beginRacePolling()}catch(error){raceError(error.message)}};\nfunction showRaceLobby(data){raceJoin.hidden=true;raceLobby.hidden=false;raceLive.hidden=true;document.querySelector('#roomCode').textContent=raceCode;document.querySelector('#startRace').hidden=raceMode!=='host';document.querySelector('#lobbyTitle').textContent=raceMode==='host'?'Waiting for racers':'You are in!';document.querySelector('#lobbyHint').textContent=raceMode==='host'?'Share the room code. Start when everyone has joined.':'Waiting for the teacher to start the race.';renderLobbyPlayers(data.players||[])}\nfunction renderLobbyPlayers(players){const box=document.querySelector('#lobbyPlayers');box.innerHTML='';if(!players.length){const empty=document.createElement('span');empty.textContent='No students yet';box.appendChild(empty);return}players.forEach(player=>{const chip=document.createElement('span');chip.textContent=`✓ ${player.name}`;box.appendChild(chip)})}\ndocument.querySelector('#copyRaceCode').onclick=async()=>{try{await navigator.clipboard.writeText(raceCode);showToast('Room code copied')}catch{showToast(`Room code: ${raceCode}`)}};\ndocument.querySelector('#startRace').onclick=async()=>{try{await raceApi('/api/race/start',{method:'POST',body:JSON.stringify({code:raceCode,hostToken:raceHostToken})})}catch(error){document.querySelector('#lobbyHint').textContent=error.message}};\nfunction beginRacePolling(){clearInterval(racePollTimer);pollRace();racePollTimer=setInterval(pollRace,850)}\nasync function pollRace(){if(!raceCode)return;try{const query=new URLSearchParams({playerId:racePlayerId,playerToken:racePlayerToken});const data=await raceApi(`/api/race/${encodeURIComponent(raceCode)}?${query}`);document.querySelector('#raceConnection').textContent='Online';if(data.status==='waiting'){renderLobbyPlayers(data.players||[]);return}if(raceLive.hidden)beginLiveRace(data);renderRace(data)}catch(error){document.querySelector('#raceConnection').textContent='Reconnecting…'}}\nfunction beginLiveRace(data){raceLobby.hidden=true;raceLive.hidden=false;racePassageText=data.passage;raceTyped='';raceStartedAt=Date.now();raceCorrect=0;raceErrors=0;renderRacePassage();renderRaceKeyboard();if(raceMode==='host')document.querySelector('#racePrompt').textContent='Teacher view — watch the racers move live.'}\nfunction renderRace(data){const players=[...(data.players||[])].sort((a,b)=>b.progress-a.progress||a.finishedAt-b.finishedAt);const track=document.querySelector('#raceTrack');track.innerHTML='';players.forEach((player,index)=>{const lane=document.createElement('div');lane.className='race-lane';const name=document.createElement('span');name.className='race-lane-name';name.textContent=`${index+1}. ${player.name}`;const car=document.createElement('span');car.className='race-car';car.textContent=carColors[player.color%carColors.length];car.style.left=`${Math.min(91,player.progress*.91)}%`;const finish=document.createElement('span');finish.className='race-finish';lane.append(name,car,finish);track.appendChild(lane)});if(racePlayerId){const me=players.find(p=>p.id===racePlayerId),place=players.findIndex(p=>p.id===racePlayerId)+1;document.querySelector('#racePosition').textContent=me?.progress>=100?`Finished · #${place}`:`#${place} · ${Math.round(me?.progress||0)}%`}else document.querySelector('#racePosition').textContent=`${players.length} racer${players.length===1?'':'s'}`;if(data.status==='finished'){document.querySelector('#raceStatusText').textContent='Race finished!';document.querySelector('#racePrompt').textContent=players[0]?`Winner: ${players[0].name}`:'Race finished';clearInterval(racePollTimer)}}\nfunction raceExpected(){if(racePassageText[raceTyped.length]===' ')return{key:'Space',value:' ',shift:false};return allMappings().find(item=>racePassageText.startsWith(item.value,raceTyped.length))||null}\nfunction renderRacePassage(){const box=document.querySelector('#racePassage');box.innerHTML='';const done=document.createElement('span');done.className='done';done.textContent=racePassageText.slice(0,raceTyped.length);const current=document.createElement('span');current.className='current';current.textContent=racePassageText.slice(raceTyped.length,raceTyped.length+1);const rest=document.createTextNode(racePassageText.slice(raceTyped.length+1));box.append(done,current,rest)}\nfunction renderRaceKeyboard(){const box=document.querySelector('#raceKeyboard');box.innerHTML='';const expected=raceExpected(),shifted=expected?.shift||false;rows.slice(1).forEach(row=>{const line=document.createElement('div');line.className='key-row';row.forEach(([key,normal,shift])=>{const button=document.createElement('button');button.type='button';button.className='key';button.innerHTML=`<small>${key}</small>${shifted?shift:normal}`;if(expected&&expected.key===key)button.classList.add('expected');button.onclick=()=>acceptRaceInput(shifted?shift:normal);line.appendChild(button)});box.appendChild(line)});const line=document.createElement('div'),space=document.createElement('button');line.className='key-row';space.type='button';space.className='key wide space';space.textContent='Space';if(expected?.key==='Space')space.classList.add('expected');space.onclick=()=>acceptRaceInput(' ');line.appendChild(space);box.appendChild(line)}\nfunction acceptRaceInput(value){if(raceMode!=='player'||raceLive.hidden||raceTyped.length>=racePassageText.length)return;const remaining=racePassageText.slice(raceTyped.length);if(remaining.startsWith(value)){raceTyped+=value;raceCorrect+=value.length;document.querySelector('#racePrompt').textContent='Keep going!';renderRacePassage();renderRaceKeyboard();scheduleRaceProgress()}else{raceErrors++;const prompt=document.querySelector('#racePrompt');prompt.textContent='Try the highlighted key.';prompt.style.color='#c92525';setTimeout(()=>prompt.style.color='',220)}}\nfunction scheduleRaceProgress(){clearTimeout(raceSendTimer);raceSendTimer=setTimeout(sendRaceProgress,120)}\nasync function sendRaceProgress(){const elapsed=Math.max(1,(Date.now()-raceStartedAt)/60000),progress=Math.min(100,raceTyped.length/racePassageText.length*100),wpm=Math.round((raceCorrect/5)/elapsed),accuracy=Math.round(raceCorrect/Math.max(1,raceCorrect+raceErrors)*100);try{await raceApi('/api/race/progress',{method:'POST',body:JSON.stringify({code:raceCode,playerId:racePlayerId,playerToken:racePlayerToken,progress,wpm,accuracy,finished:progress>=100})})}catch{}if(progress>=100)document.querySelector('#racePrompt').textContent=`Finished! ${wpm} WPM · ${accuracy}% accuracy`}\ndocument.addEventListener('keydown',e=>{if(raceStage.hidden||raceLive.hidden||raceMode!=='player'||e.ctrlKey||e.metaKey||e.altKey||e.key==='Shift')return;let value;if(e.code==='Space')value=' ';else{const key=physicalKey(e),mapping=rows.flat().find(([mapped])=>mapped===key);if(!mapping)return;value=e.shiftKey?mapping[2]:mapping[1]}e.preventDefault();acceptRaceInput(value)});\n","type":"text/javascript; charset=UTF-8"},"/logo.png":{"base64":"","type":"image/png"}};
const PASSAGES=[
  'မိၢ် ပၢ် မိၢ်ပၢ် ဖိခွါ ဖိမုၣ် ဟံၣ်ဖိဃီဖိ',
  'မုၢ်ဒဲး မုၢ်ဆၣ် မုၢ်ယူာ် ကိးနံၤဒဲး ကိးဂီၤဒဲး',
  'မ့ၤ တၢ်အီၣ် ညၣ် ဆီညၣ် ကိးဟါဒဲး ကိးနၤဒဲး'
];
const CODE_CHARS='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const json=(value,status=200)=>new Response(JSON.stringify(value),{status,headers:{'content-type':'application/json; charset=UTF-8','cache-control':'no-store'}});
const token=()=>crypto.randomUUID().replaceAll('-','');
const code=()=>Array.from({length:5},()=>CODE_CHARS[Math.floor(Math.random()*CODE_CHARS.length)]).join('');
const cleanName=value=>String(value||'').trim().replace(/\s+/g,' ').slice(0,24);
async function body(request){try{return await request.json()}catch{return{}}}
async function roomState(db,roomCode){const room=await db.prepare('SELECT code, passage, status, created_at, started_at, finished_at FROM race_rooms WHERE code = ?').bind(roomCode).first();if(!room)return null;const result=await db.prepare('SELECT id, name, progress, wpm, accuracy, color, joined_at, finished_at FROM race_players WHERE room_code = ? ORDER BY progress DESC, joined_at ASC').bind(roomCode).all();return{code:room.code,passage:room.passage,status:room.status,createdAt:room.created_at,startedAt:room.started_at,finishedAt:room.finished_at,players:(result.results||[]).map(player=>({id:player.id,name:player.name,progress:Number(player.progress),wpm:player.wpm,accuracy:player.accuracy,color:player.color,joinedAt:player.joined_at,finishedAt:player.finished_at}))}}
async function createRace(env){const now=Date.now();await env.DB.prepare('DELETE FROM race_rooms WHERE created_at < ?').bind(now-14400000).run();for(let attempt=0;attempt<8;attempt++){const roomCode=code(),hostToken=token(),passage=PASSAGES[Math.floor(Math.random()*PASSAGES.length)];try{await env.DB.prepare('INSERT INTO race_rooms (code, host_token, passage, status, created_at) VALUES (?, ?, ?, ?, ?)').bind(roomCode,hostToken,passage,'waiting',now).run();return json({code:roomCode,hostToken,passage,status:'waiting',players:[]},201)}catch(error){if(!String(error).toLowerCase().includes('unique'))throw error}}return json({error:'Could not create a room. Please try again.'},503)}
async function joinRace(request,env){const data=await body(request),roomCode=String(data.code||'').trim().toUpperCase(),name=cleanName(data.name);if(!/^[A-Z2-9]{5}$/.test(roomCode))return json({error:'Enter a valid five-letter room code.'},400);if(name.length<1)return json({error:'Enter your name.'},400);const room=await env.DB.prepare('SELECT status, created_at FROM race_rooms WHERE code = ?').bind(roomCode).first();if(!room||room.created_at<Date.now()-14400000)return json({error:'Room not found. Check the code.'},404);if(room.status!=='waiting')return json({error:'This race has already started.'},409);const count=await env.DB.prepare('SELECT COUNT(*) AS total FROM race_players WHERE room_code = ?').bind(roomCode).first();if(Number(count.total)>=30)return json({error:'This room is full.'},409);const playerId=token(),playerToken=token();try{await env.DB.prepare('INSERT INTO race_players (id, room_code, name, player_token, color, joined_at) VALUES (?, ?, ?, ?, ?, ?)').bind(playerId,roomCode,name,playerToken,Number(count.total)%6,Date.now()).run()}catch{return json({error:'That name is already in this room. Add an initial.'},409)}const state=await roomState(env.DB,roomCode);return json({...state,playerId,playerToken},201)}
async function startRace(request,env){const data=await body(request),roomCode=String(data.code||'').toUpperCase();const room=await env.DB.prepare('SELECT host_token, status FROM race_rooms WHERE code = ?').bind(roomCode).first();if(!room||room.host_token!==data.hostToken)return json({error:'Only the teacher who created this room can start it.'},403);if(room.status!=='waiting')return json({error:'The race has already started.'},409);const count=await env.DB.prepare('SELECT COUNT(*) AS total FROM race_players WHERE room_code = ?').bind(roomCode).first();if(!Number(count.total))return json({error:'Wait for at least one student to join.'},409);await env.DB.prepare("UPDATE race_rooms SET status = 'racing', started_at = ? WHERE code = ? AND status = 'waiting'").bind(Date.now(),roomCode).run();return json({ok:true})}
async function updateProgress(request,env){const data=await body(request),roomCode=String(data.code||'').toUpperCase(),playerId=String(data.playerId||'');const player=await env.DB.prepare('SELECT player_token, progress FROM race_players WHERE id = ? AND room_code = ?').bind(playerId,roomCode).first();if(!player||player.player_token!==data.playerToken)return json({error:'Player session not found.'},403);const room=await env.DB.prepare('SELECT status FROM race_rooms WHERE code = ?').bind(roomCode).first();if(!room||room.status!=='racing')return json({error:'This race is not running.'},409);const progress=Math.max(Number(player.progress)||0,Math.min(100,Math.max(0,Number(data.progress)||0))),wpm=Math.min(500,Math.max(0,Math.round(Number(data.wpm)||0))),accuracy=Math.min(100,Math.max(0,Math.round(Number(data.accuracy)||0))),finished=progress>=100?Date.now():null;await env.DB.prepare('UPDATE race_players SET progress = ?, wpm = ?, accuracy = ?, finished_at = COALESCE(finished_at, ?) WHERE id = ? AND room_code = ?').bind(progress,wpm,accuracy,finished,playerId,roomCode).run();if(finished){const remaining=await env.DB.prepare('SELECT COUNT(*) AS total FROM race_players WHERE room_code = ? AND progress < 100').bind(roomCode).first();if(!Number(remaining.total))await env.DB.prepare("UPDATE race_rooms SET status = 'finished', finished_at = ? WHERE code = ? AND status = 'racing'").bind(Date.now(),roomCode).run()}return json({ok:true,progress})}
async function getRace(roomCode,env){const state=await roomState(env.DB,roomCode.toUpperCase());if(!state||state.createdAt<Date.now()-14400000)return json({error:'Room not found.'},404);return json(state)}
async function api(request,env,url){if(!env.DB)return json({error:'Race storage is unavailable.'},503);if(request.method==='POST'&&url.pathname==='/api/race/create')return createRace(env);if(request.method==='POST'&&url.pathname==='/api/race/join')return joinRace(request,env);if(request.method==='POST'&&url.pathname==='/api/race/start')return startRace(request,env);if(request.method==='POST'&&url.pathname==='/api/race/progress')return updateProgress(request,env);const match=url.pathname.match(/^\/api\/race\/([A-Z2-9]{5})$/i);if(request.method==='GET'&&match)return getRace(match[1],env);return json({error:'Not found.'},404)}
export default{async fetch(request,env){const url=new URL(request.url);try{if(url.pathname.startsWith('/api/'))return await api(request,env,url);const path=url.pathname==='/'?'/':url.pathname.replace(/\/$/,'');const asset=ASSETS[path]||ASSETS['/'];const content=asset.base64?Uint8Array.from(atob(asset.base64),character=>character.charCodeAt(0)):asset.body;return new Response(content,{headers:{'content-type':asset.type,'cache-control':path==='/'?'no-cache':'public, max-age=300','x-content-type-options':'nosniff'}})}catch(error){return json({error:'The race service had a problem. Please try again.'},500)}}};
